```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, notifier};
use wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {}s: fetched {} chars from {}", seconds, fetched, feed_url);

        // The contract requires notified == true; retry, and trap rather than
        // emit a report that violates it.
        let mut notified = false;
        for _ in 0..3 {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
